\begin{document}

% Cross-section 2: x = 1 (hyperbola in yz-plane)
\begin{tikzpicture}
\begin{axis}[
    width=8cm,
    height=7cm,
    xlabel={$y$},
    ylabel={$z$},
    title={Cross-section at $x = 1$ \\ $-(y-1)^2 + (z+2)^2 = 2$},
    grid=major,
    axis lines=center,
    domain=-3:5,
    samples=200,
    ]
    % Upper branch: z = -2 + sqrt(2 + (y-1)^2)
    \addplot[magenta, thick] {-2 + sqrt(2 + (x-1)^2)};
    % Lower branch: z = -2 - sqrt(2 + (y-1)^2)
    \addplot[magenta, thick] {-2 - sqrt(2 + (x-1)^2)};
    \addplot[gray, dashed] coordinates {(-3,-2) (5,-2)};
    \addplot[gray, dashed] coordinates {(1,-6) (1,2)};
\end{axis}
\end{tikzpicture}

\end{document}

